#!/usr/bin/env bash
# PreToolUse hook for Claude Code (Edit|Write|MultiEdit).
#
# Reads the hook JSON payload on stdin and blocks (exit 2, reason on stderr)
# edits to:
#   - the generated API types:          src/api/generated/**
#   - the vendored API contract:        api/openapi.yaml, api/core-version.json
#   - native projects generated by CNG: ios/**, android/**
#
# Any other situation (unparseable input, no file path) exits 0 so the hook
# never blocks unrelated work.
set -u

input="$(cat || true)"

json_file_path() {
	if command -v jq >/dev/null 2>&1; then
		printf '%s' "$1" | jq -r '.tool_input.file_path // .tool_input.path // empty' 2>/dev/null
		return
	fi
	if command -v python3 >/dev/null 2>&1; then
		printf '%s' "$1" | python3 -I -c '
import json, sys
try:
    data = json.load(sys.stdin)
    ti = data.get("tool_input") or {}
    print(ti.get("file_path") or ti.get("path") or "")
except Exception:
    pass
' 2>/dev/null
	fi
}

file_path="$(json_file_path "$input")"
[ -n "$file_path" ] || exit 0

# Resolve the repository root: prefer the project dir given by Claude Code.
root="${CLAUDE_PROJECT_DIR:-}"
if [ -z "$root" ]; then
	root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
fi
root="${root%/}"

# Repository-relative path (absolute paths outside the repo are left untouched).
case "$file_path" in
/*)
	case "$file_path" in
	"$root"/*) rel="${file_path#"$root"/}" ;;
	*)
		# Handle symlinked roots (e.g. /tmp vs /private/tmp on macOS).
		real_root="$(cd "$root" 2>/dev/null && pwd -P || printf '%s' "$root")"
		case "$file_path" in
		"$real_root"/*) rel="${file_path#"$real_root"/}" ;;
		*) exit 0 ;;
		esac
		;;
	esac
	;;
*) rel="${file_path#./}" ;;
esac

block() {
	printf 'BLOCKED by scripts/agents/guard-generated.sh: %s\n%s\n' "$rel" "$1" >&2
	exit 2
}

case "$rel" in
src/api/generated/*)
	block "These are the API types generated from the pinned core contract. Run 'make gen' (or 'make api-bump VERSION=vX.Y.Z' to pin another core release) instead."
	;;
api/openapi.yaml | api/core-version.json)
	block "The API contract is the verbatim openapi.yaml of a pinned core release, checked by SHA-256 (ADR 0002). Change it only with 'make api-bump VERSION=vX.Y.Z'; API changes start in the core repository."
	;;
ios/* | android/*)
	block "Native projects are generated by Expo prebuild (Continuous Native Generation). Configure native behaviour in app.json or a config plugin instead."
	;;
esac

exit 0
